use super::{admission_tests::{Fixture,evidence},authority::Authority,authority_tests::{root,queued},authority_store::Fault as AuthFault,lease_controller::{Controller,Validity},model::{self,Record,Action,State},recovery_controller::{Prepared,Review},reconciliation_tests::inventory,store::{Store,Fault}};
use crate::{chat::Chat,spotify::goal::tests::Bus};
use std::{fs,process::{Command,Child,Stdio},time::{Duration,Instant},sync::Arc};
struct ChildGuard(Child);impl Drop for ChildGuard{fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}
pub(super)struct Environment{pub(super)fixture:Fixture,pub(super)goal:Record,pub(super)authority:Authority,pub(super)store:Store,child:ChildGuard,_parent:Fixture,_bus:Bus,_connection:dbus::blocking::Connection,_claim:Option<Box<dyn std::any::Any>>}
impl Environment{
    pub(super)fn new(provider:&str,phase:&str,kill:bool)->Self{
        let parent=Fixture::new();let path=parent.path.join("coucou");let ready=parent.path.join("ready.json");let bus=Bus::new();let child=ChildGuard(Command::new(std::env::current_exe().unwrap()).args(["--exact","pet_runtime::native_owner::tests::native_owner_child","--ignored","--nocapture"]).env("COUCOU_OWNER_PROFILE_NATIVE",&path).env("COUCOU_OWNER_BUS_NATIVE",&bus.address).env("COUCOU_OWNER_READY_NATIVE",&ready).env("COUCOU_OWNER_PROVIDER_NATIVE",provider).env("COUCOU_OWNER_RECOVERY_PHASE",phase).stdout(Stdio::null()).stderr(Stdio::null()).spawn().unwrap());
        let mut child=child;let until=Instant::now()+Duration::from_secs(5);while !ready.exists(){assert!(Instant::now()<until&&child.0.try_wait().unwrap().is_none(),"private native owner failed readiness");std::thread::sleep(Duration::from_millis(10));}
        let info:serde_json::Value=serde_json::from_slice(&fs::read(&ready).unwrap()).unwrap();let fixture=Fixture{path};let authority=Authority::existing(&root(&fixture)).unwrap();let store=Store::existing_verified(&fixture.path.join("goals"),&root(&fixture)).unwrap().unwrap();let goal=store.read(info["goalId"].as_str().unwrap(),info["petId"].as_str().unwrap()).unwrap();let connection=dbus::blocking::Connection::new_address(&bus.address).unwrap();let mut env=Self{fixture,goal,authority,store,child,_parent:parent,_bus:bus,_connection:connection,_claim:None};if kill{env.kill();}env
    }
    fn kill(&mut self){self.child.0.kill().unwrap();self.child.0.wait().unwrap();assert_eq!(self._connection.request_name("com.coucou.OwnerFixture.SingleInstance",false,false,true).unwrap(),dbus::blocking::stdintf::org_freedesktop_dbus::RequestNameReply::PrimaryOwner);let claim=crate::pet_data::fixture_native_claim(&self._bus.address,"com.coucou.OwnerFixture",&self.fixture.path).unwrap();claim.current().unwrap();self._claim=Some(Box::new(claim));}
    pub(super)fn review(&self,request:&str)->Review{self.review_at(request,100_020)}
    fn review_at(&self,request:&str,now:u64)->Review{match self.store.prepare_recovery(&root(&self.fixture),&self.goal.id,&self.goal.spec.owner.pet_id,&self.goal.revision,request.into(),now).unwrap(){Prepared::Review(r)=>r,_=>panic!("original lost owner must require a review")}}
    pub(super)fn grant(&self)->serde_json::Value{serde_json::from_slice::<serde_json::Value>(&fs::read(root(&self.fixture).join(format!("{}.json",self.goal.admissions[0].spec.decision_id))).unwrap()).unwrap()["body"].clone()}
}
#[test]fn every_native_pet_can_close_its_actual_lost_owner_without_replaying_or_resetting_unknown_usage(){
    for provider in ["codex","copilot","antigravity","ollama"]{
        let env=Environment::new(provider,"started",true);let before=env.grant();let files=inventory(&env.fixture.path);let review=env.review("review-lost");assert_eq!(inventory(&env.fixture.path),files);assert_eq!(review.proposal().approval_scope,"closeLostExecution");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);let r=approved.confirm(&env.store,100_022).unwrap();assert_eq!(r.record.state,State::RecoveryRequired);assert_eq!(r.record.schema_version,9);assert_eq!(r.record.spec,env.goal.spec);assert_eq!(r.record.execution_context,env.goal.execution_context);let after=env.grant();assert_eq!(after["phase"],"closed");assert_eq!(after["schemaVersion"],7);for k in ["budgetUsage","planningUsage","resourceUsage","runtimeOwner","lease","approvedAt"]{assert_eq!(after.get(k),before.get(k));}assert_eq!(after["budgetUsage"]["attempts"][0]["phase"],"started");assert_eq!(after["budgetUsage"]["attempts"][0]["outputReserved"],512);
        let reference=approved.closure.reference.clone();let again=approved.confirm(&env.store,300_000).unwrap();assert_eq!(again.record.revision,r.record.revision);assert_eq!(env.grant(),after);let ack=approved.acknowledged();assert_eq!(ack.receipt(&env.store).unwrap().record.revision,reference.target_goal_revision);
    }
}
#[test]fn actual_live_owner_and_expired_review_cannot_close_and_decline_writes_nothing(){
    let mut env=Environment::new("ollama","started",false);let before=inventory(&env.fixture.path);assert!(env.store.prepare_recovery(&root(&env.fixture),&env.goal.id,"ai_ollama",&env.goal.revision,"live-refusal".into(),100_020).is_err());assert_eq!(inventory(&env.fixture.path),before);env.kill();let before=inventory(&env.fixture.path);let review=env.review("expiry");assert!(review.decide(130_021).is_err());drop(review);assert_eq!(inventory(&env.fixture.path),before);drop(env.review("decline"));assert_eq!(inventory(&env.fixture.path),before);
}
#[test]fn uncertain_goal_publication_keeps_one_approved_native_transaction_and_blocks_control_until_ack(){
    for fault in [Fault::BeforePublish,Fault::AfterPublish]{
        let mut env=Environment::new("ollama","started",true);let review=env.review("partial-goal");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);let source=env.grant();env.store.fault=fault;let first=approved.confirm(&env.store,100_022);if matches!(fault,Fault::BeforePublish){assert_eq!(first.err(),Some(model::Error::StorageUnavailable));assert_eq!(env.store.mutate(&env.goal.id,"ai_ollama",&env.goal.revision,"cancel-before-ack".into(),Action::Cancel,100_023).err(),Some(model::Error::Busy));}else{assert_eq!(first.unwrap().status,model::CommitStatus::Uncertain);}
        let closed=env.grant();assert_eq!(closed["budgetUsage"],source["budgetUsage"]);env.store.fault=Fault::None;let r=approved.confirm(&env.store,300_000).unwrap();assert_eq!(r.record.state,State::RecoveryRequired);assert_eq!(env.grant(),closed);assert_eq!(r.record.events.iter().filter(|e|matches!(e.kind,model::EventKind::LostOwnerClosed)).count(),1);
    }
}
#[test]fn uncertain_grant_publication_retains_approval_and_retries_only_the_same_close(){
    for fault in [AuthFault::BeforeGrantPublish,AuthFault::AfterGrantPublish]{
        let env=Environment::new("ollama","started",true);let review=env.review("partial-grant");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);let original=env.grant();approved.authority.fault=fault;assert_eq!(approved.confirm(&env.store,100_022).err(),Some(model::Error::StorageUnavailable));assert!(approved.write_started);assert_eq!(env.store.read_control(&env.goal.id,"ai_ollama").unwrap().revision,env.goal.revision);approved.authority.fault=AuthFault::None;let closed=approved.confirm(&env.store,300_000).unwrap();assert_eq!(closed.record.state,State::RecoveryRequired);assert_eq!(env.grant()["budgetUsage"],original["budgetUsage"]);assert_eq!(env.grant()["recovery"]["reference"]["approvedAt"],100_021);
    }
}
#[test]fn signed_recorded_closure_survives_lost_cache_and_requires_only_its_original_ack(){
    let env=Environment::new("ollama","started",true);let review=env.review("original-choice");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);approved.authority.fault=AuthFault::AfterGrantPublish;assert!(approved.confirm(&env.store,100_022).is_err());let signed=env.grant();drop(approved);
    let review=env.review_at("new-ui-request",300_000);assert_eq!(review.proposal().approval_scope,"ackRecordedClosure");let decision=review.decide(300_000).unwrap();let mut resumed=review.approve(decision);let receipt=resumed.confirm(&env.store,300_001).unwrap();assert_eq!(receipt.record.state,State::RecoveryRequired);assert_eq!(env.grant(),signed);drop(resumed);
    let again=env.store.prepare_recovery(&root(&env.fixture),&env.goal.id,"ai_ollama",&receipt.record.revision,"after-restart".into(),300_002).unwrap();assert!(matches!(again,Prepared::Closed(_)));
}
#[test]fn an_unpublished_claim_is_closed_as_audit_without_fabricating_an_activation(){
    let env=Environment::new("ollama","unclaimed",true);assert!(env.goal.admissions[0].lease.is_none());let review=env.review("unclaimed-close");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);let r=approved.confirm(&env.store,100_022).unwrap();assert_eq!(r.record.state,State::RecoveryRequired);assert!(r.record.admissions[0].lease.is_some());assert!(!r.record.events.iter().any(|e|matches!(e.kind,model::EventKind::LeaseClaimed)));assert_eq!(r.record.events.iter().filter(|e|matches!(e.kind,model::EventKind::UnclaimedOwnerClosed)).count(),1);
}
#[test]fn another_native_pet_and_a_manual_same_provider_hold_remain_operational_during_closure(){
    let env=Environment::new("ollama","started",true);let draft=env.fixture.goal("codex");let goal=queued(&env.fixture,&draft,&env.authority);let main=Chat::persistent(env.fixture.path.join("other-main.json"));let hold=main.runtime_resources().acquire("ollama",Arc::default(),None).unwrap();let controller=Controller::new().unwrap();let pending=controller.prepare(&goal,&root(&env.fixture),&env.fixture.path.join("contexts"),&main,&evidence(&goal,100_006),"other-claim".into(),100_006,Arc::new(|_,_,_|Validity::Current)).unwrap();let(_,owner)=pending.claim(&env.store,&env.authority,&evidence(&goal,100_007),100_007).unwrap();let owner=owner.unwrap();let review=env.review("close-independent");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);approved.confirm(&env.store,100_022).unwrap();assert!(hold.current());assert!(owner.current(100_023));assert!(main.runtime_resources().acquire("ollama",Arc::default(),None).is_err());assert_eq!(env.store.read(&goal.id,"agent_codex").unwrap().state,State::Leased);
}
#[test]fn a_new_native_model_receipt_after_review_invalidates_the_choice_without_closing_or_changing_usage(){
    let env=Environment::new("ollama","settled",true);let review=env.review("receipt-fence");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);let row=&env.goal.admissions[0];let proof=row.proof.as_ref().unwrap();let(lease,call)=env.authority.result_attempt(&row.spec,proof,"original-model").unwrap();let call=call.unwrap();let receipt=env.authority.seal_result(&row.spec,proof,&lease.unwrap(),&call,"Free signed fixture",64,100_022).unwrap();super::results::publish(&env.authority,&row.spec,proof,&receipt).unwrap();let before=inventory(&env.fixture.path);assert_eq!(approved.confirm(&env.store,100_023).err(),Some(model::Error::Conflict));assert!(!approved.write_started);assert_eq!(inventory(&env.fixture.path),before);
}
#[test]fn a_cancelled_source_stays_cancelled_and_old_ack_cannot_overwrite_a_later_control(){
    let mut env=Environment::new("ollama","started",true);env.goal=super::authority_store::mutate_with_authority(&env.store,&root(&env.fixture),&env.goal.id,"ai_ollama",&env.goal.revision,"cancel-before-review".into(),Action::Cancel,100_015).unwrap().record;let review=env.review("close-cancelled");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);let closed=approved.confirm(&env.store,100_022).unwrap();assert_eq!(closed.record.state,State::Cancelled);assert_eq!(env.grant()["phase"],"revoked");let ack=approved.acknowledged();assert_eq!(ack.receipt(&env.store).unwrap().record.revision,closed.record.revision);
    let env=Environment::new("ollama","started",true);let review=env.review("close-before-cancel");let decision=review.decide(100_021).unwrap();let mut approved=review.approve(decision);let closed=approved.confirm(&env.store,100_022).unwrap();let ack=approved.acknowledged();let cancelled=super::authority_store::mutate_with_authority(&env.store,&root(&env.fixture),&env.goal.id,"ai_ollama",&closed.record.revision,"later-cancel".into(),Action::Cancel,100_023).unwrap();assert_eq!(ack.receipt(&env.store).unwrap().record.revision,cancelled.record.revision);assert_eq!(cancelled.record.state,State::Cancelled);
}
